/**
 * ==========================================================
 * INFOGENX STUDENT ONBOARDING SYSTEM
 * SETUP.GS
 * ==========================================================
 */

const PROJECT_NAME = "Infogenx Student Onboarding";
const DATABASE_NAME = "Infogenx Student Database";

/**
 * ----------------------------------------------------------
 * CREATE PROJECT DATABASE
 * ----------------------------------------------------------
 */
function setupProject() {

  // Create Spreadsheet
  const spreadsheet = SpreadsheetApp.create(DATABASE_NAME);

  // Save Database ID
  PropertiesService.getScriptProperties().setProperty(
    "DATABASE_ID",
    spreadsheet.getId()
  );

  // Rename Default Sheet
  const studentsSheet = spreadsheet.getSheets()[0];
  studentsSheet.setName("Students");

  // Create Config Sheet
  const configSheet = spreadsheet.insertSheet("Config");

  // -----------------------------
  // Students Sheet Headers
  // -----------------------------
  const headers = [[
    "Registration Date",
    "Full Name",
    "Date of Birth",
    "Email",
    "Generated Password",
    "Password Hash",
    "Mobile Number",
    "City",
    "Highest Qualification",
    "College Name",
    "Department",
    "Year of Passing",
    "Skill Category",
    "Skills",
    "Experience Type",
    "Company Name",
    "Experience (Years)",
    "Current Salary",
    "Expected Salary",
    "Resume Link",
    "Preferred Time",
    "Status",
    "Created At",
    "Last Login"
  ]];

  studentsSheet
    .getRange(1, 1, 1, headers[0].length)
    .setValues(headers);

  studentsSheet
    .getRange(1, 1, 1, headers[0].length)
    .setFontWeight("bold")
    .setFontColor("#FFFFFF")
    .setBackground("#0F62FE")
    .setHorizontalAlignment("center");

  studentsSheet.setFrozenRows(1);
  studentsSheet.autoResizeColumns(1, headers[0].length);

  // -----------------------------
  // Config Sheet
  // -----------------------------
  const configData = [
    ["Project Name", PROJECT_NAME],
    ["Version", "1.0"],
    ["Database Name", DATABASE_NAME],
    ["Created On", new Date()],
    ["Default Status", "Active"],
    ["Password Rule", "First 4 letters of Name + Birth Year"],
    ["Developer", "Infogenx"]
  ];

  configSheet
    .getRange(1, 1, configData.length, 2)
    .setValues(configData);

  configSheet
    .getRange(1, 1, configData.length, 1)
    .setFontWeight("bold")
    .setBackground("#E8F0FE");

  configSheet.autoResizeColumns(1, 2);

  Logger.log("====================================");
  Logger.log("PROJECT CREATED SUCCESSFULLY");
  Logger.log("Spreadsheet URL:");
  Logger.log(spreadsheet.getUrl());
  Logger.log("====================================");
}

/**
 * ==========================================================
 * INFOGENX STUDENT ONBOARDING SYSTEM
 * FORM.GS
 * ==========================================================
 */

/**
 * ==========================================================
 * CREATE NEW REGISTRATION FORM
 * ==========================================================
 *
 * IMPORTANT:
 * Run this function ONLY when you actually need to create
 * a NEW registration form.
 *
 * Do NOT run this again if your existing form is already
 * connected and being used.
 */
function createRegistrationForm() {

  // Get Database ID
  const databaseId = PropertiesService
    .getScriptProperties()
    .getProperty("DATABASE_ID");

  if (!databaseId) {
    throw new Error(
      "DATABASE_ID not found. Run setupProject() first."
    );
  }

  // Open Spreadsheet
  const spreadsheet = SpreadsheetApp.openById(databaseId);

  // Create Google Form
  const form = FormApp.create(
    "Infogenx Internship Registration"
  );

  // Form title
  form.setTitle(
    "Infogenx Internship Registration"
  );

  // Form description
  form.setDescription(
    "Welcome to Infogenx Student Onboarding.\n\n" +
    "Please fill all the required details carefully.\n\n" +
    "Your password will be generated automatically and " +
    "sent to your registered email."
  );

  // Save Form ID
  PropertiesService
    .getScriptProperties()
    .setProperty("FORM_ID", form.getId());

  // Link Form to Spreadsheet
  form.setDestination(
    FormApp.DestinationType.SPREADSHEET,
    spreadsheet.getId()
  );


  /**
   * ========================================================
   * PERSONAL INFORMATION
   * ========================================================
   */

  form.addTextItem()
    .setTitle("Full Name")
    .setRequired(true);

  form.addDateItem()
    .setTitle("Date of Birth")
    .setRequired(true);

  form.addTextItem()
    .setTitle("Email Address")
    .setRequired(true);

  form.addTextItem()
    .setTitle("Mobile Number")
    .setRequired(true);

  form.addTextItem()
    .setTitle("City")
    .setRequired(true);


  /**
   * ========================================================
   * EDUCATION
   * ========================================================
   */

  form.addListItem()
    .setTitle("Highest Qualification")
    .setChoiceValues([
      "SSLC",
      "HSC",
      "Diploma",
      "UG",
      "PG",
      "Other"
    ])
    .setRequired(true);

  form.addTextItem()
    .setTitle("College Name")
    .setRequired(true);

  form.addTextItem()
    .setTitle("Department")
    .setRequired(true);

  form.addTextItem()
    .setTitle("Year of Passing")
    .setRequired(true);


  /**
   * ========================================================
   * SKILLS
   * ========================================================
   */

  form.addMultipleChoiceItem()
    .setTitle("Skill Category")
    .setChoiceValues([
      "IT",
      "Non-IT"
    ])
    .setRequired(true);

  form.addParagraphTextItem()
    .setTitle("Skills")
    .setHelpText(
      "Example: HTML, CSS, JavaScript, React"
    )
    .setRequired(true);


  /**
   * ========================================================
   * EXPERIENCE
   * ========================================================
   */

  form.addMultipleChoiceItem()
    .setTitle("Experience Type")
    .setChoiceValues([
      "Fresher",
      "Experienced"
    ])
    .setRequired(true);

  form.addTextItem()
    .setTitle("Company Name")
    .setHelpText(
      "If Fresher, enter NA"
    )
    .setRequired(true);

  form.addTextItem()
    .setTitle("Experience (Years)")
    .setHelpText(
      "Example: 0, 1, 2.5"
    )
    .setRequired(true);

  form.addTextItem()
    .setTitle("Current Salary")
    .setHelpText(
      "If Fresher, enter NA"
    )
    .setRequired(true);

  form.addTextItem()
    .setTitle("Expected Salary")
    .setRequired(true);


  /**
   * ========================================================
   * RESUME
   * ========================================================
   */

  form.addTextItem()
    .setTitle("Resume Google Drive Link")
    .setRequired(true);


  /**
   * ========================================================
   * AVAILABILITY
   * ========================================================
   */

  form.addTextItem()
    .setTitle("Preferred Time")
    .setHelpText(
      "Example: Full-Time / Part-Time / Flexible"
    )
    .setRequired(true);


  /**
   * ========================================================
   * ADDITIONAL CANDIDATE INFORMATION
   * ========================================================
   */

  form.addTextItem()
    .setTitle("Certification")
    .setHelpText(
      "Enter your certification details. If none, enter NA."
    )
    .setRequired(true);

  form.addTextItem()
    .setTitle("LinkedIn Profile URL")
    .setHelpText(
      "Paste your LinkedIn profile URL."
    )
    .setRequired(true);

  form.addTextItem()
    .setTitle("Work Duration & Timings")
    .setHelpText(
      "Example: 10 AM - 7 PM / Full-Time"
    )
    .setRequired(true);

  form.addDateItem()
    .setTitle("Start Date")
    .setRequired(true);

  form.addTextItem()
    .setTitle(
      "Current Monthly Take Home Salary / Hourly Rate"
    )
    .setHelpText(
      "If not working, enter NA."
    )
    .setRequired(true);

  form.addMultipleChoiceItem()
    .setTitle("Your Current Work Status")
    .setChoiceValues([
      "Freelancer",
      "Working in an Organisation",
      "Not working"
    ])
    .setRequired(true);

  form.addMultipleChoiceItem()
    .setTitle("If Working then")
    .setChoiceValues([
      "Hybrid",
      "WFH all days with Fixed Day/Hours",
      "Flexible"
    ])
    .setRequired(true);

  form.addParagraphTextItem()
    .setTitle("Preferred Availability")
    .setHelpText(
      "Mention your preferred weekday and weekend " +
      "time slots."
    )
    .setRequired(true);


  /**
   * ========================================================
   * LOGGING
   * ========================================================
   */

  Logger.log(
    "===================================="
  );

  Logger.log(
    "FORM CREATED SUCCESSFULLY"
  );

  Logger.log(
    "Form URL:"
  );

  Logger.log(
    form.getPublishedUrl()
  );

  Logger.log(
    "Form ID:"
  );

  Logger.log(
    form.getId()
  );

  Logger.log(
    "===================================="
  );
}


/**
 * ==========================================================
 * ADD ADDITIONAL FIELDS TO EXISTING FORM
 * ==========================================================
 *
 * IMPORTANT:
 * Use this function ONLY if the existing form was already
 * created using the old FORM.GS code.
 *
 * It will add ONLY the new fields.
 *
 * It will NOT create a new form.
 *
 * It will NOT duplicate the existing Resume field.
 * ==========================================================
 */
function addCandidateDetailsToExistingForm() {

  // Get existing Form ID
  const formId = PropertiesService
    .getScriptProperties()
    .getProperty("FORM_ID");

  if (!formId) {
    throw new Error(
      "FORM_ID not found. Please check Script Properties."
    );
  }

  // Open existing form
  const form = FormApp.openById(formId);

  /**
   * --------------------------------------------------------
   * Check existing item titles before adding anything.
   * This prevents accidental duplicate fields.
   * --------------------------------------------------------
   */

  const existingTitles = form
    .getItems()
    .map(function(item) {
      return item.getTitle();
    });


  /**
   * ========================================================
   * CERTIFICATION
   * ========================================================
   */

  if (!existingTitles.includes("Certification")) {

    form.addTextItem()
      .setTitle("Certification")
      .setHelpText(
        "Enter your certification details. If none, enter NA."
      )
      .setRequired(true);
  }


  /**
   * ========================================================
   * LINKEDIN
   * ========================================================
   */

  if (!existingTitles.includes("LinkedIn Profile URL")) {

    form.addTextItem()
      .setTitle("LinkedIn Profile URL")
      .setHelpText(
        "Paste your LinkedIn profile URL."
      )
      .setRequired(true);
  }


  /**
   * ========================================================
   * WORK DURATION & TIMINGS
   * ========================================================
   */

  if (!existingTitles.includes("Work Duration & Timings")) {

    form.addTextItem()
      .setTitle("Work Duration & Timings")
      .setHelpText(
        "Example: 10 AM - 7 PM / Full-Time"
      )
      .setRequired(true);
  }


  /**
   * ========================================================
   * START DATE
   * ========================================================
   */

  if (!existingTitles.includes("Start Date")) {

    form.addDateItem()
      .setTitle("Start Date")
      .setRequired(true);
  }


  /**
   * ========================================================
   * CURRENT TAKE HOME / HOURLY RATE
   * ========================================================
   */

  if (
    !existingTitles.includes(
      "Current Monthly Take Home Salary / Hourly Rate"
    )
  ) {

    form.addTextItem()
      .setTitle(
        "Current Monthly Take Home Salary / Hourly Rate"
      )
      .setHelpText(
        "If not working, enter NA."
      )
      .setRequired(true);
  }


  /**
   * ========================================================
   * CURRENT WORK STATUS
   * ========================================================
   */

  if (
    !existingTitles.includes(
      "Your Current Work Status"
    )
  ) {

    form.addMultipleChoiceItem()
      .setTitle(
        "Your Current Work Status"
      )
      .setChoiceValues([
        "Freelancer",
        "Working in an Organisation",
        "Not working"
      ])
      .setRequired(true);
  }


  /**
   * ========================================================
   * WORKING TYPE
   * ========================================================
   */

  if (
    !existingTitles.includes(
      "If Working then"
    )
  ) {

    form.addMultipleChoiceItem()
      .setTitle(
        "If Working then"
      )
      .setChoiceValues([
        "Hybrid",
        "WFH all days with Fixed Day/Hours",
        "Flexible"
      ])
      .setRequired(true);
  }


  /**
   * ========================================================
   * PREFERRED AVAILABILITY
   * ========================================================
   */

  if (
    !existingTitles.includes(
      "Preferred Availability"
    )
  ) {

    form.addParagraphTextItem()
      .setTitle(
        "Preferred Availability"
      )
      .setHelpText(
        "Mention your preferred weekday and weekend " +
        "time slots."
      )
      .setRequired(true);
  }


  /**
   * ========================================================
   * UPDATE FORM TITLE
   * ========================================================
   */

  form.setTitle(
    "Infogenx Internship Registration"
  );


  /**
   * ========================================================
   * LOGGING
   * ========================================================
   */

  Logger.log(
    "===================================="
  );

  Logger.log(
    "EXISTING FORM UPDATED SUCCESSFULLY"
  );

  Logger.log(
    "Form URL:"
  );

  Logger.log(
    form.getPublishedUrl()
  );

  Logger.log(
    "===================================="
  );
}

/**
 * ==========================================================
 * INFOGENX STUDENT ONBOARDING SYSTEM
 * DATABASE.GS
 * ==========================================================
 */


/**
 * ==========================================================
 * GET DATABASE ID
 * ==========================================================
 */

function getDatabaseId() {

  return PropertiesService
    .getScriptProperties()
    .getProperty("DATABASE_ID");

}


/**
 * ==========================================================
 * GET STUDENTS SHEET
 * ==========================================================
 */

function getStudentsSheet() {

  const databaseId = getDatabaseId();

  if (!databaseId) {

    throw new Error(
      "DATABASE_ID not found. Run setupProject() first."
    );

  }

  const spreadsheet =
    SpreadsheetApp.openById(databaseId);

  const sheet =
    spreadsheet.getSheetByName("Students");

  if (!sheet) {

    throw new Error(
      "Students sheet not found."
    );

  }

  return sheet;

}


/**
 * ==========================================================
 * REMOVE EXTRA SPACES
 * ==========================================================
 */

function cleanText(value) {

  if (
    value === null ||
    value === undefined
  ) {

    return "";

  }

  return value
    .toString()
    .trim();

}


/**
 * ==========================================================
 * CONVERT TO UPPERCASE
 * ==========================================================
 */

function toUpper(value) {

  return cleanText(value)
    .toUpperCase();

}


/**
 * ==========================================================
 * GENERATE PASSWORD
 *
 * Example:
 *
 * Priyadharshini
 * 22/03/2006
 *
 * Output:
 * PRIY2006
 * ==========================================================
 */

function generatePassword(name, dob) {

  const firstPart =
    toUpper(name).substring(0, 4);

  const birthYear =
    new Date(dob).getFullYear();

  return firstPart + birthYear;

}


/**
 * ==========================================================
 * GENERATE SHA-256 PASSWORD HASH
 * ==========================================================
 */

function generatePasswordHash(password) {

  const bytes =
    Utilities.computeDigest(
      Utilities.DigestAlgorithm.SHA_256,
      password
    );

  return bytes
    .map(function (b) {

      const value =
        (b + 256) % 256;

      return (
        "0" +
        value.toString(16)
      ).slice(-2);

    })
    .join("");

}


/**
 * ==========================================================
 * VALIDATE EMAIL
 * ==========================================================
 */

function isValidEmail(email) {

  email =
    cleanText(email);

  const regex =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  return regex.test(email);

}


/**
 * ==========================================================
 * VALIDATE MOBILE NUMBER
 * ==========================================================
 */

function isValidMobile(number) {

  number =
    cleanText(number);

  return /^[6-9]\d{9}$/.test(number);

}


/**
 * ==========================================================
 * CHECK DUPLICATE EMAIL
 * ==========================================================
 */

function isEmailExists(email) {

  email =
    cleanText(email)
      .toLowerCase();

  const sheet =
    getStudentsSheet();

  const data =
    sheet.getDataRange()
      .getValues();

  for (
    let i = 1;
    i < data.length;
    i++
  ) {

    const savedEmail =
      cleanText(data[i][3])
        .toLowerCase();

    if (
      savedEmail === email
    ) {

      return true;

    }

  }

  return false;

}


/**
 * ==========================================================
 * SAVE STUDENT
 * ==========================================================
 */

function saveStudent(student) {

  const sheet =
    getStudentsSheet();


  /**
   * --------------------------------------------------------
   * CLEAN DATA
   * --------------------------------------------------------
   */

  student.fullName =
    cleanText(student.fullName);

  student.email =
    cleanText(student.email)
      .toLowerCase();

  student.mobile =
    cleanText(student.mobile);

  student.city =
    cleanText(student.city);

  student.qualification =
    cleanText(student.qualification);

  student.college =
    cleanText(student.college);

  student.department =
    cleanText(student.department);

  student.yearOfPassing =
    cleanText(student.yearOfPassing);

  student.skillCategory =
    cleanText(student.skillCategory);

  student.skills =
    cleanText(student.skills);

  student.experienceType =
    cleanText(student.experienceType);

  student.companyName =
    cleanText(student.companyName);

  student.experienceYears =
    cleanText(student.experienceYears);

  student.currentSalary =
    cleanText(student.currentSalary);

  student.expectedSalary =
    cleanText(student.expectedSalary);

  student.resumeLink =
    cleanText(student.resumeLink);

  student.preferredTime =
    cleanText(student.preferredTime);


  /**
   * --------------------------------------------------------
   * NEW CANDIDATE DETAILS
   * --------------------------------------------------------
   */

  student.certification =
    cleanText(student.certification);

  student.linkedinUrl =
    cleanText(student.linkedinUrl);

  student.workDurationTimings =
    cleanText(
      student.workDurationTimings
    );

  student.startDate =
    cleanText(student.startDate);

  student.currentTakeHomeSalaryHourlyRate =
    cleanText(
      student.currentTakeHomeSalaryHourlyRate
    );

  student.currentWorkStatus =
    cleanText(
      student.currentWorkStatus
    );

  student.workingType =
    cleanText(
      student.workingType
    );

  student.preferredAvailability =
    cleanText(
      student.preferredAvailability
    );


  /**
   * --------------------------------------------------------
   * VALIDATION
   * --------------------------------------------------------
   */

  if (!student.fullName) {

    throw new Error(
      "Full Name is required."
    );

  }


  if (
    !isValidEmail(
      student.email
    )
  ) {

    throw new Error(
      "Invalid Email Address."
    );

  }


  if (
    !isValidMobile(
      student.mobile
    )
  ) {

    throw new Error(
      "Invalid Mobile Number."
    );

  }


  /**
   * --------------------------------------------------------
   * DUPLICATE EMAIL CHECK
   * --------------------------------------------------------
   */

  if (
    isEmailExists(
      student.email
    )
  ) {

    throw new Error(
      "Email already registered."
    );

  }


  /**
   * --------------------------------------------------------
   * GENERATE PASSWORD
   * --------------------------------------------------------
   */

  const password =
    generatePassword(
      student.fullName,
      student.dob
    );


  /**
   * --------------------------------------------------------
   * GENERATE PASSWORD HASH
   * --------------------------------------------------------
   */

  const passwordHash =
    generatePasswordHash(
      password
    );


  /**
   * ========================================================
   * SAVE STUDENT TO GOOGLE SHEET
   * ========================================================
   *
   * IMPORTANT:
   *
   * Existing columns A:X are preserved.
   * New candidate fields are saved after Last Login.
   *
   * ========================================================
   */

  sheet.appendRow([

    // A
    new Date(),

    // B
    student.fullName,

    // C
    student.dob,

    // D
    student.email,

    // E
    password,

    // F
    passwordHash,

    // G
    student.mobile,

    // H
    student.city,

    // I
    student.qualification,

    // J
    student.college,

    // K
    student.department,

    // L
    student.yearOfPassing,

    // M
    student.skillCategory,

    // N
    student.skills,

    // O
    student.experienceType,

    // P
    student.companyName,

    // Q
    student.experienceYears,

    // R
    student.currentSalary,

    // S
    student.expectedSalary,

    // T
    student.resumeLink,

    // U
    student.preferredTime,

    // V
    "Active",

    // W
    new Date(),

    // X
    "",


    // ======================================================
    // NEW CANDIDATE INFORMATION
    // ======================================================

    // Y
    student.certification,

    // Z
    student.linkedinUrl,

    // AA
    student.workDurationTimings,

    // AB
    student.startDate,

    // AC
    student.currentTakeHomeSalaryHourlyRate,

    // AD
    student.currentWorkStatus,

    // AE
    student.workingType,

    // AF
    student.preferredAvailability,

    // ======================================================
    // ASSESSMENT COLUMNS
    // ======================================================

    // AG
    "",

    // AH
    "",

    // AI
    "",

    // AJ
    "",

    // ======================================================
    // TASK
    // ======================================================

    // AK
    "Not Started"

  ]);


  /**
   * --------------------------------------------------------
   * RETURN RESULT
   * --------------------------------------------------------
   */

  return {

    success: true,

    password:
      password,

    message:
      "Student Registered Successfully."

  };

}

/**
 * ==========================================================
 * INFOGENX STUDENT ONBOARDING SYSTEM
 * FORM SUBMIT TRIGGER
 * ==========================================================
 *
 * Handles Google Form submissions and converts the
 * submitted answers into a student object.
 *
 * IMPORTANT:
 * The saveStudent(student) function must support the
 * additional fields as well.
 * ==========================================================
 */

function onStudentRegistration(e) {

  try {

    // -------------------------------------------------------
    // Validate Form Response
    // -------------------------------------------------------

    if (!e || !e.response) {
      throw new Error("Form response not found.");
    }

    const responses = e.response.getItemResponses();


    // -------------------------------------------------------
    // Student Object
    // -------------------------------------------------------

    const student = {

      // Personal Information
      fullName: "",
      dob: "",
      email: "",
      mobile: "",
      city: "",

      // Education
      qualification: "",
      college: "",
      department: "",
      yearOfPassing: "",

      // Skills
      skillCategory: "",
      skills: "",

      // Experience
      experienceType: "",
      companyName: "",
      experienceYears: "",
      currentSalary: "",
      expectedSalary: "",

      // Resume
      resumeLink: "",

      // Existing Availability
      preferredTime: "",

      // ---------------------------------------------------
      // NEW CANDIDATE DETAILS
      // ---------------------------------------------------

      certification: "",
      linkedinUrl: "",
      workDurationTimings: "",
      startDate: "",
      currentTakeHomeSalaryHourlyRate: "",
      currentWorkStatus: "",
      workingType: "",
      preferredAvailability: ""

    };


    // -------------------------------------------------------
    // Read Form Responses
    // -------------------------------------------------------

    responses.forEach(function(response) {

      const title = response.getItem().getTitle();
      const answer = response.getResponse();


      switch (title) {

        // =================================================
        // PERSONAL INFORMATION
        // =================================================

        case "Full Name":
          student.fullName = answer;
          break;

        case "Date of Birth":
          student.dob = answer;
          break;

        case "Email Address":
          student.email = answer;
          break;

        case "Mobile Number":
          student.mobile = answer;
          break;

        case "City":
          student.city = answer;
          break;


        // =================================================
        // EDUCATION
        // =================================================

        case "Highest Qualification":
          student.qualification = answer;
          break;

        case "College Name":
          student.college = answer;
          break;

        case "Department":
          student.department = answer;
          break;

        case "Year of Passing":
          student.yearOfPassing = answer;
          break;


        // =================================================
        // SKILLS
        // =================================================

        case "Skill Category":
          student.skillCategory = answer;
          break;

        case "Skills":
          student.skills = answer;
          break;


        // =================================================
        // EXPERIENCE
        // =================================================

        case "Experience Type":
          student.experienceType = answer;
          break;

        case "Company Name":
          student.companyName = answer;
          break;

        case "Experience (Years)":
          student.experienceYears = answer;
          break;

        case "Current Salary":
          student.currentSalary = answer;
          break;

        case "Expected Salary":
          student.expectedSalary = answer;
          break;


        // =================================================
        // RESUME
        // =================================================

        case "Resume Google Drive Link":
          student.resumeLink = answer;
          break;


        // =================================================
        // EXISTING AVAILABILITY
        // =================================================

        case "Preferred Time":
          student.preferredTime = answer;
          break;


        // =================================================
        // NEW CANDIDATE DETAILS
        // =================================================

        case "Certification":
          student.certification = answer;
          break;

        case "LinkedIn Profile URL":
          student.linkedinUrl = answer;
          break;

        case "Work Duration & Timings":
          student.workDurationTimings = answer;
          break;

        case "Start Date":
          student.startDate = answer;
          break;

        case "Current Monthly Take Home Salary / Hourly Rate":
          student.currentTakeHomeSalaryHourlyRate = answer;
          break;

        case "Your Current Work Status":
          student.currentWorkStatus = answer;
          break;

        case "If Working then":
          student.workingType = answer;
          break;

        case "Preferred Availability":
          student.preferredAvailability = answer;
          break;

      }

    });


    // -------------------------------------------------------
    // Validate Required Student Information
    // -------------------------------------------------------

    if (!student.fullName) {
      throw new Error("Full Name is missing.");
    }

    if (!student.email) {
      throw new Error("Email Address is missing.");
    }

    if (!student.mobile) {
      throw new Error("Mobile Number is missing.");
    }


    // -------------------------------------------------------
    // Save Student
    // -------------------------------------------------------

    const result = saveStudent(student);

    if (!result || !result.success) {
      throw new Error(
        result && result.message
          ? result.message
          : "Unable to save student."
      );
    }


    // -------------------------------------------------------
    // Welcome Email
    // -------------------------------------------------------

    sendWelcomeEmail(
      student.email,
      student.fullName,
      result.password
    );


    // -------------------------------------------------------
    // Candidate SMS
    // -------------------------------------------------------
    //
    // Keeping the existing registration SMS for now.
    // Assessment-result SMS will NOT be used.
    //
    // If you later want to completely remove registration
    // SMS as well, we can remove this separately.
    // -------------------------------------------------------

    sendCandidateSMS(
      student,
      result.password
    );


    // -------------------------------------------------------
    // HR SMS
    // -------------------------------------------------------
    //
    // Existing registration notification.
    // Assessment result notification will be EMAIL only.
    //
    // -------------------------------------------------------

    sendHRSMS(student);


    Logger.log(
      "Student Registered Successfully: " +
      student.fullName +
      " (" +
      student.email +
      ")"
    );


  } catch (err) {

    Logger.log(
      "Registration Error: " +
      err.message
    );

    throw err;
  }

}


/**
 * ==========================================================
 * CREATE FORM SUBMIT TRIGGER
 * ==========================================================
 *
 * Run this function ONLY when the trigger needs to be
 * created/recreated.
 *
 * It removes the old onStudentRegistration trigger first,
 * then creates one new trigger.
 * ==========================================================
 */

function createFormTrigger() {

  const formId = PropertiesService
    .getScriptProperties()
    .getProperty("FORM_ID");


  if (!formId) {

    throw new Error(
      "FORM_ID not found. Please check Script Properties."
    );

  }


  // -------------------------------------------------------
  // Open Existing Form
  // -------------------------------------------------------

  const form = FormApp.openById(formId);


  // -------------------------------------------------------
  // Delete Existing Trigger
  // -------------------------------------------------------

  const triggers = ScriptApp.getProjectTriggers();


  triggers.forEach(function(trigger) {

    if (
      trigger.getHandlerFunction() ===
      "onStudentRegistration"
    ) {

      ScriptApp.deleteTrigger(trigger);

    }

  });


  // -------------------------------------------------------
  // Create New Trigger
  // -------------------------------------------------------

  ScriptApp
    .newTrigger("onStudentRegistration")
    .forForm(form)
    .onFormSubmit()
    .create();


  Logger.log(
    "Form Submit Trigger Created Successfully."
  );

}

