/**
 * ----------------------------------------------------------
 * POST API
 * ----------------------------------------------------------
 */
function doPost(e) {

  try {

    let request = {}

if (e.parameter && Object.keys(e.parameter).length > 0) {
  request = e.parameter
} else {
  request = JSON.parse(e.postData.contents)
}

    switch (request.action) {

      case "login":

        return jsonResponse(
          authenticateStudent(
            request.email,
            request.password
          )
        );

      default:

        return jsonResponse({
          success: false,
          message: "Invalid Action."
        });

    }

  } catch (err) {

    return jsonResponse({
      success: false,
      message: err.message
    });

  }

}

/**
